<?php require_once __DIR__ . '/partials.php'; require_admin(); $service = null; if (!empty($_GET['id'])) { $service = find_service((int) $_GET['id']); } admin_header($service ? 'Edit Service' : 'Add Service'); ?>
<section class="panel"><form class="admin-form" action="../actions/save-service" method="post"><input type="hidden" name="id" value="<?= (int) ($service['id'] ?? 0) ?>"><label>Name<input name="name" value="<?= e($service['name'] ?? '') ?>" required></label><label>Slug<input name="slug" value="<?= e($service['slug'] ?? '') ?>" required></label><label>Description<textarea name="description" rows="5" required><?= e($service['description'] ?? '') ?></textarea></label><label>Price<input type="number" step="0.01" name="price" value="<?= e((string) ($service['price'] ?? '0')) ?>" required></label><label class="check"><input type="checkbox" name="is_active" value="1" <?= empty($service) || !empty($service['is_active']) ? 'checked' : '' ?>> Active</label><button class="admin-btn" type="submit">Save Service</button></form></section>
<?php admin_footer(); ?>
